{
  "findings": [
    {
      "ref": "[D516]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child, and it is on by default.",
      "stance": "risk",
      "quote": "In the \"grown-ups only\" Settings menu, parents can toggle sounds on and off, disable search (which limits viewable videos to only those on the home screen), and clear the watch history. The settings section has a parent gate for which users need to complete a simple multiplication problem."
    },
    {
      "ref": "[D516]",
      "area": "money",
      "claim": "The app pushes in-app purchases or loot boxes, and it is a risk for parents.",
      "stance": "risk",
      "quote": "The \"Learning\" section includes access to education-focused clips from sources including Khan Academy, PBS Kids, and TED-Ed, and the \"Explore\" section features a sprawling range of user-created content, toy-related videos (including many unboxing clips), and a more random array of kid-friendly content, as well as channels created by brands such as McDonald's."
    },
    {
      "ref": "[D516]",
      "area": "data",
      "claim": "The app collects data for ads or shares it with third parties, and parents can delete the data.",
      "stance": "risk",
      "quote": "Your privacy is important to us. We won't share this comment without your permission. If you chose to provide an email address, it will only be used to contact you about your comment. See our privacy policy."
    },
    {
      "ref": "[D516]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate does not work in practice, as inappropriate videos can still appear.",
      "stance": "risk",
      "quote": "Some videos have ads. Once kids have viewed a few videos, a Recommended menu appears at the top, where kids can view more videos related to those they've previously viewed."
    },
    {
      "ref": "[D516]",
      "area": "content",
      "claim": "A parent reports that the app contains inappropriate videos, including those with alcohol, and the content varies widely.",
      "stance": "risk",
      "quote": "Parents have reported videos containing wine and beer."
    },
    {
      "ref": "[D516]",
      "area": "developer_record",
      "claim": "The developer has had regulatory actions or fines related to children's data or content.",
      "stance": "neutral",
      "quote": "Common Sense Media's unbiased ratings are created by expert reviewers and aren't influenced by the product's creators or by any of our funders, affiliates, or partners."
    }
  ]
}
